    companion object {
        val ISSUE = Issue.create(
            id = "BannedGlobalScope",
            briefDescription = "يحظر استخدام GlobalScope نهائياً",
            explanation = "يتسبب GlobalScope في تسريب الذاكرة وكسر التزامن الهيكلي. استخدم viewModelScope أو نطاقاً محقوناً.",
